@Command([EditDocument]; "1");

@If(Company= "";	@Return(@Do(@Command([EditGotoField];"Company");		@Prompt([Ok];"Missing Value"; "Please select Company!")));"");
@If(Designation= "";	@Return(@Do(@Command([EditGotoField];"Designation");	@Prompt([Ok];"Missing Value"; "Please state your Designation!")));"");
@If(DocType= "";		@Return(@Do(@Command([EditGotoField];"DocType");		@Prompt([Ok];"Missing Value"; "Please select Document Type!")));"");
@If(Title= "";				@Return(@Do(@Command([EditGotoField];"Title");				@Prompt([Ok];"Missing Value"; "Please state the Title of form!")));"");
@If(Department= "";	@Return(@Do(@Command([EditGotoField];"Department");	@Prompt([Ok];"Missing Value"; "Please select Department!")));"");
@If(Location= "";		@Return(@Do(@Command([EditGotoField];"Location");		@Prompt([Ok];"Missing Value"; "Please select Location!")));"");
@If(ExpDate= "";		@Return(@Do(@Command([EditGotoField];"ExpDate");		@Prompt([Ok];"Missing Value"; "Please select Expected date of using document!")));"");
@If(Custodian= "";	@Return(@Do(@Command([EditGotoField];"Custodian");		@Prompt([Ok];"Missing Value"; "Please state the Custodian of document!")));"");
@If(Retention= "";		@Return(@Do(@Command([EditGotoField];"Retention");		@Prompt([Ok];"Missing Value"; "Please state the Retention period!")));"");
@If(Justification= "";	@Return(@Do(@Command([EditGotoField];"Justification");	@Prompt([Ok];"Missing Value"; "Please state Justification of the document!")));"");

FIELD CurrentAction := "Submitted";
FIELD Requestor := @V3UserName;
FIELD DateReq := @Today ;

@Command([FileSave]);
@MailSend(QA;CC;NULL;"Pancen Issuance of Record Number - SUBMITTED - "+FormNo;NULL;"Please follow this doclink  ------> ";[IncludeDoclink]);

@Command([ViewRefreshFields]);
@PostedCommand([FileSave]);
@Command([FileCloseWindow])

@Command([EditDocument]; "1");

@If(NewDocNo= "";	@Return(@Do(@Command([EditGotoField];"NewDocNo");	@Prompt([Ok];"Missing Value"; "Please state New Document Number!")));"");
