@If(Comment= "";		@Return(@Do(@Command([EditGotoField];"Comment");		@Prompt([Ok];"Missing Value"; "Please state the Comment!")));"");

FIELD CurrentAction := "Replied";
FIELD QAApp := 1;
FIELD Issuedby := @V3UserName;
FIELD DateIssued := @Today ;

@MailSend(DocAuthor;QA:CC:CC2;NULL;"Pancen Issuance of Record Number - REPLIED - "+FormNo;NULL;"Comment : "+@NewLine +@Implode(Comment)+@NewLine+@NewLine+"Please follow this doclink  ------> ";[IncludeDoclink]);

