@MailSend(DocAuthor;QA:CC;NULL;"Pancen Issuance of Record Number - REJECTED - "+FormNo;NULL;"Comment : "+@NewLine +@Implode(Comment)+@NewLine+@NewLine+"Please follow this doclink  ------> ";[IncludeDoclink]);

