FIELD CA					 	:= "Submitted";
FIELD PreName			:= @Name([CN];@V3UserName);
FIELD PreDate			:= @Today ;

@Command([FileSave]);
@MailSend(QA;DocAuthor:CC;NULL;"Disposition Record - SUBMITTED - "+DisNo;NULL;"Please follow this doclink  ------> ";[IncludeDoclink]);

